$root=Split-Path $PSScriptRoot -Parent;$runtime=Join-Path $root 'web\.runtime';foreach($name in @('fastapi','vite')){$file=Join-Path $runtime "$name.pid";if(!(Test-Path $file)){continue};$id=[int](Get-Content $file);$p=Get-Process -Id $id -ErrorAction SilentlyContinue;if($p){$cmd=(Get-CimInstance Win32_Process -Filter "ProcessId=$id").CommandLine;if(($name -eq 'fastapi' -and $cmd -match 'uvicorn.*8100') -or ($name -eq 'vite' -and $cmd -match 'vite|npm')){Stop-Process -Id $id -Force;Write-Host "Stopped $name PID $id"}else{Write-Warning "PID $id no longer matches $name; not stopped."}}}
